using System.Diagnostics.CodeAnalysis;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using Validly.Utils;

namespace Validly;

/// <summary>
/// Error message generated by the validator
/// </summary>
/// <param name="Message">Translated message, or default message (e.g., in English); may contain placeholders (e.g., {0}) for the <paramref name="Args"/></param>
/// <param name="Code">Stable, public identifier of the error, e.g. "Validations.LengthBetween"; usable as a localization key</param>
/// <param name="Args">Positional arguments of the <paramref name="Message"/></param>
public sealed partial record ValidationMessage(
	[StringSyntax(StringSyntaxAttribute.CompositeFormat)] string Message,
	string Code,
	params object?[] Args
)
{
	// Lazily computed JSON; cached for the instance of the arguments it was computed for (records can be cloned by "with")
	private object?[]? _argsJsonSource;
	private string? _argsJson;
	private IReadOnlyList<KeyValuePair<string, object?>>? _namedArgsJsonSource;
	private string? _namedArgsJson;

	/// <summary>
	/// Empty validation message
	/// </summary>
	public static ValidationMessage Empty = new(string.Empty, string.Empty);

	/// <summary>
	/// Resource key for localization
	/// </summary>
	[Obsolete("Use Code. ResourceKey is an alias of Code.")]
	public string ResourceKey => Code;

	/// <summary>
	/// Named arguments, e.g. ("min", 5), ("max", 20); usable for message templates with named placeholders
	/// </summary>
	public IReadOnlyList<KeyValuePair<string, object?>>? NamedArgs { get; init; }

	/// <summary>
	/// String with comma-separated list of arguments converted to JSON strings
	/// </summary>
	/// <remarks>
	/// Prepared to be used within array brackets like: $"[{ArgsJson}]"
	/// </remarks>
	public string ArgsJson
	{
		get
		{
			object?[] args = Args;

			if (!ReferenceEquals(_argsJsonSource, args) || _argsJson is null)
			{
				_argsJson = args.Length == 0 ? string.Empty : string.Join(", ", args.Select(SerializeArgument));
				_argsJsonSource = args;
			}

			return _argsJson;
		}
	}

	/// <summary>
	/// Comma-separated list of the <see cref="NamedArgs"/> as JSON object members ("name": value);
	/// empty string when there are no named arguments
	/// </summary>
	/// <remarks>
	/// Prepared to be used within object braces like: $"{{{NamedArgsJson}}}"
	/// </remarks>
	public string NamedArgsJson
	{
		get
		{
			var namedArgs = NamedArgs;

			if (namedArgs is null || namedArgs.Count == 0)
			{
				return string.Empty;
			}

			if (!ReferenceEquals(_namedArgsJsonSource, namedArgs) || _namedArgsJson is null)
			{
				var sb = new StringBuilder();

				for (int index = 0; index < namedArgs.Count; index++)
				{
					if (index != 0)
					{
						sb.Append(", ");
					}

					sb.Append('"')
						.Append(JsonEscaper.Escape(namedArgs[index].Key))
						.Append("\": ")
						.Append(SerializeArgument(namedArgs[index].Value));
				}

				_namedArgsJson = sb.ToString();
				_namedArgsJsonSource = namedArgs;
			}

			return _namedArgsJson;
		}
	}

	/// <inheritdoc />
	public bool Equals(ValidationMessage? other)
	{
		return other is not null
			&& (
				ReferenceEquals(this, other)
				|| (
					Message == other.Message
					&& Code == other.Code
					&& ReferenceEquals(Args, other.Args)
					&& ReferenceEquals(NamedArgs, other.NamedArgs)
				)
			);
	}

	/// <inheritdoc />
	public override int GetHashCode()
	{
		unchecked
		{
			return ((Message?.GetHashCode() ?? 0) * 397) ^ (Code?.GetHashCode() ?? 0);
		}
	}

	private static string SerializeArgument(object? argument) =>
		argument is null ? "null" : JsonSerializer.Serialize(argument, ArgumentJsonContext.Default.Object);

	[JsonSerializable(typeof(object))]
	[JsonSerializable(typeof(string))]
	[JsonSerializable(typeof(char))]
	[JsonSerializable(typeof(decimal))]
	[JsonSerializable(typeof(double))]
	[JsonSerializable(typeof(float))]
	[JsonSerializable(typeof(bool))]
	[JsonSerializable(typeof(byte))]
	[JsonSerializable(typeof(short))]
	[JsonSerializable(typeof(int))]
	[JsonSerializable(typeof(uint))]
	[JsonSerializable(typeof(long))]
	[JsonSerializable(typeof(ulong))]
	[JsonSerializable(typeof(Guid))]
	[JsonSerializable(typeof(DateTime))]
	[JsonSerializable(typeof(TimeSpan))]
	[JsonSerializable(typeof(DateTimeOffset))]
#if NET5_0_OR_GREATER
	[JsonSerializable(typeof(DateOnly))]
	[JsonSerializable(typeof(TimeOnly))]
#endif
	[JsonSourceGenerationOptions(GenerationMode = JsonSourceGenerationMode.Serialization)]
	private partial class ArgumentJsonContext : JsonSerializerContext;
}
